<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Clinic;use App\Models\ClinicNotificationSetting;use Illuminate\Http\Request;
class ClinicNotificationSettingController extends Controller{public function index($clinic){$c=Clinic::findOrFail($clinic);return response()->json(['success'=>true,'data'=>$c->notificationSettings]);}public function update(Request $r,$clinic){Clinic::findOrFail($clinic);$rows=$r->validate(['settings'=>'required|array','settings.*.event_key'=>'required|string|max:80','settings.*.panel_enabled'=>'required|boolean','settings.*.sms_enabled'=>'required|boolean','settings.*.panel_title'=>'nullable|string|max:190','settings.*.panel_template'=>'nullable|string|max:2000','settings.*.sms_template'=>'nullable|string|max:1000'])['settings'];foreach($rows as $row)ClinicNotificationSetting::updateOrCreate(['clinic_id'=>$clinic,'event_key'=>$row['event_key']],$row);return $this->index($clinic);}}
